    "id": "Semester 3-DBMS-Module 1-5_Entity_Types_and_Sets",
    "relPath": "Semester 3/DBMS/Module 1/5_Entity_Types_and_Sets.md",
    "pdfPath": "PDF_Notes/Semester 3/DBMS/Module 1/5_Entity_Types_and_Sets.pdf",
    "filename": "5_Entity_Types_and_Sets.md",
    "semester": "Semester 3",
