    "id": "Semester 3-DBMS-Module 2-6_Cartesian_Product_Operation",
    "relPath": "Semester 3/DBMS/Module 2/6_Cartesian_Product_Operation.md",
    "pdfPath": "PDF_Notes/Semester 3/DBMS/Module 2/6_Cartesian_Product_Operation.pdf",
