    "id": "Semester 3-DBMS-Module 3-3_Set_Operations",
    "relPath": "Semester 3/DBMS/Module 3/3_Set_Operations.md",
    "pdfPath": "PDF_Notes/Semester 3/DBMS/Module 3/3_Set_Operations.pdf",
