    "id": "Semester 3-DBMS-Module 4-4_Boyce_Codd_Normal_Form_BCNF",
    "relPath": "Semester 3/DBMS/Module 4/4_Boyce_Codd_Normal_Form_BCNF.md",
    "pdfPath": "PDF_Notes/4_Boyce_Codd_Normal_Form_BCNF.pdf",
