    "id": "Semester 3-DBMS-Module 5-Module_5_QA-5M",
    "relPath": "Semester 3/DBMS/Module 5/Module_5_QA/5M.md",
    "pdfPath": "PDF_Notes/5M.pdf",
    "filename": "5M.md",
    "semester": "Semester 3",
