    "id": "Semester 3-Data Structure-Module 2-B3_Deque_Introduction",
    "relPath": "Semester 3/Data Structure/Module 2/B3_Deque_Introduction.md",
    "pdfPath": "PDF_Notes/Semester 3/Data Structure/Module 2/B3_Deque_Introduction.pdf",
    "filename": "B3_Deque_Introduction.md",
    "semester": "Semester 3",
