    "id": "Semester 3-Data Structure-Module 3-4_Operations_on_Singly_Linked_List",
    "relPath": "Semester 3/Data Structure/Module 3/4_Operations_on_Singly_Linked_List.md",
    "pdfPath": "PDF_Notes/Semester 3/Data Structure/Module 3/4_Operations_on_Singly_Linked_List.pdf",
    "filename": "4_Operations_on_Singly_Linked_List.md",
